/* data/cs-c/cs-12-04.js - GENERATED by tools/build.py from data/cs/cs-12-04.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-04"] = [{"id":"cs-12-04-01","kind":"short","q":"What is HTML ?","marks":3,"src":["Guide ch.4 HTML, Q.1"],"model":[{"t":"HTML stands for Hyper Text Markup Language. It is the language used to make web pages.","m":1},{"t":"A page is written with tags that tell the browser how to show the text, pictures, links and tables.","m":1},{"t":"It is a markup language, not a programming language: it describes the page, it does not calculate.","m":1}]},{"id":"cs-12-04-02","kind":"short","q":"What is Internet ?","marks":3,"src":["Guide ch.4 HTML, Q.2"],"model":[{"t":"The Internet is a worldwide network that joins millions of computer networks.","m":1},{"t":"It uses a common set of rules (TCP/IP) so that the computers can exchange data.","m":1},{"t":"It gives services such as the web, e-mail, file transfer and chat.","m":1}]},{"id":"cs-12-04-03","kind":"short","q":"What is www ?","marks":3,"src":["Guide ch.4 HTML, Q.3"],"model":[{"t":"WWW means World Wide Web. It is a service on the Internet.","m":1},{"t":"It is a huge collection of web pages joined to each other by hyperlinks, stored on web servers.","m":1},{"t":"Pages are seen with a web browser, and each page has an address called a URL.","m":1}]},{"id":"cs-12-04-04","kind":"short","q":"What is Web browser ?","marks":3,"src":["Guide ch.4 HTML, Q.4"],"model":[{"t":"A web browser is a program used to find, fetch and show web pages.","m":1},{"t":"It reads the HTML code of the page and shows it as text, pictures and links.","m":1},{"t":"Examples: Google Chrome, Mozilla Firefox, Microsoft Edge.","m":1}]},{"id":"cs-12-04-05","kind":"short","q":"What are advantages of HTML ?","marks":4,"src":["Guide ch.4 HTML, Q.5"],"model":[{"t":"It is simple and easy to learn, and a page can be written in any text editor.","m":1},{"t":"It is free, and it is supported by all browsers and all computers (platform independent).","m":1},{"t":"Pages are small and load fast, and links join pages and sites.","m":1},{"t":"It can show text, pictures, tables, sound and video.","m":1}]},{"id":"cs-12-04-06","kind":"short","q":"What are limitations of HTML ?","marks":4,"src":["Guide ch.4 HTML, Q.6"],"model":[{"t":"HTML makes static pages; it cannot do calculations or take decisions by itself.","m":1},{"t":"It has no real security for the data of a page.","m":1},{"t":"A big page needs a lot of code, and it is hard to keep the same style in many pages.","m":1},{"t":"Different browsers may show the same page a little differently.","m":1}]},{"id":"cs-12-04-07","kind":"short","q":"What is HTML tag ?","marks":3,"src":["Guide ch.4 HTML, Q.7"],"model":[{"t":"A tag is an instruction written inside angle brackets < > that tells the browser how to show something.","m":1},{"t":"Most tags come in pairs: a start tag <B> and an end tag </B>, with the text in between.","m":1},{"t":"Some tags, such as <BR> and <HR>, have no end tag (empty tags). Tag names are not case sensitive.","m":1}]},{"id":"cs-12-04-08","kind":"short","q":"What is structure of HTML web page ?","marks":4,"src":["Guide ch.4 HTML, Q.8"],"model":[{"t":"A web page starts with <HTML> and ends with </HTML>.","m":1},{"t":"The <HEAD> part comes first and holds the title of the page: <TITLE> ... </TITLE>.","m":1},{"t":"The <BODY> part holds everything that is shown in the window: text, pictures, links and tables.","m":1},{"t":"Example: <HTML><HEAD><TITLE>My page</TITLE></HEAD><BODY>Hello</BODY></HTML>","m":1}]},{"id":"cs-12-04-09","kind":"short","q":"What is <HTML> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.9"],"model":[{"t":"The <HTML> tag is the first tag of a web page; it tells the browser that this is an HTML document.","m":1},{"t":"It has an end tag </HTML> at the very end of the page.","m":1},{"t":"All the other tags (HEAD and BODY) are written between them.","m":1}]},{"id":"cs-12-04-10","kind":"short","q":"What is <HEAD> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.10"],"model":[{"t":"The <HEAD> tag starts the head section of the page, which comes before the body.","m":1},{"t":"It holds information about the page, mainly the <TITLE> tag. The head is not shown in the page area.","m":1},{"t":"It ends with </HEAD>.","m":1}]},{"id":"cs-12-04-11","kind":"short","q":"What is <TITLE> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.11"],"model":[{"t":"The <TITLE> tag gives the title of the web page.","m":1},{"t":"It is written inside the <HEAD> section: <TITLE> My Web Page </TITLE>","m":1},{"t":"The title is shown in the title bar of the browser window and is used for bookmarks.","m":1}]},{"id":"cs-12-04-12","kind":"short","q":"What is <BODY> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.12"],"model":[{"t":"The <BODY> tag starts the body of the page: everything that is shown in the browser window.","m":1},{"t":"Its attributes set the page background and text, for example BGCOLOR, TEXT, LINK and BACKGROUND.","m":1},{"t":"It ends with </BODY>, just before </HTML>.","m":1}]},{"id":"cs-12-04-13","kind":"short","q":"What is <P> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.13"],"model":[{"t":"The <P> tag starts a new paragraph. The browser leaves a blank line before it.","m":1},{"t":"The end tag </P> is optional.","m":1},{"t":"Its ALIGN attribute sets the position: left, center or right.","m":1}]},{"id":"cs-12-04-14","kind":"short","q":"What is <BR> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.14"],"model":[{"t":"The <BR> tag breaks the line: the text after it begins on the next line.","m":1},{"t":"It is an empty tag, so it has no end tag.","m":1},{"t":"It does not leave a blank line, unlike <P>. Use it for addresses and poems.","m":1}]},{"id":"cs-12-04-15","kind":"short","q":"How ALIGN attribute is used with <P> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.15"],"model":[{"t":"The ALIGN attribute sets how the paragraph is placed in the window.","m":1},{"t":"Values: left (the default), center and right, as in <P ALIGN=\"center\"> text </P>.","m":1},{"t":"It works only for that paragraph.","m":1}]},{"id":"cs-12-04-16","kind":"short","q":"What is use of <HR> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.16"],"model":[{"t":"The <HR> tag draws a horizontal line (rule) across the page, to separate parts of the page.","m":1},{"t":"It is an empty tag with no end tag.","m":1},{"t":"Attributes: WIDTH, SIZE (thickness), ALIGN and NOSHADE, as in <HR WIDTH=\"50%\" SIZE=\"3\">.","m":1}]},{"id":"cs-12-04-17","kind":"short","q":"What are different levels of headings ?","marks":3,"src":["Guide ch.4 HTML, Q.17"],"model":[{"t":"HTML has six levels of headings: <H1> to <H6>, each with an end tag, like <H1> ... </H1>.","m":1},{"t":"<H1> is the biggest and most important. <H6> is the smallest.","m":1},{"t":"A heading is shown in bold and a blank line is left before and after it.","m":1}]},{"id":"cs-12-04-18","kind":"short","q":"How text is formatted with <B>, <I> and <U> tags ?","marks":4,"src":["Guide ch.4 HTML, Q.18"],"model":[{"t":"<B> makes the text bold: <B>Hello</B>.","m":1},{"t":"<I> makes the text italic: <I>Hello</I>.","m":1},{"t":"<U> underlines the text: <U>Hello</U>.","m":1},{"t":"The tags can be used together (nested): <B><I>Hello</I></B>, closing the inner tag first.","m":1}]},{"id":"cs-12-04-19","kind":"short","q":"Differentiate between <B> and <EM> tag.","marks":3,"src":["Guide ch.4 HTML, Q.19"],"model":[{"t":"<B> is a physical tag: it only makes the text bold.","m":1},{"t":"<EM> is a logical tag: it marks the text as emphasised, and the browser decides how to show it (usually in italics).","m":1},{"t":"So <B> says how to look, and <EM> says what the text means.","m":1}]},{"id":"cs-12-04-20","kind":"short","q":"What is <LI> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.20"],"model":[{"t":"The <LI> tag (list item) writes one item of a list.","m":1},{"t":"It is used inside <UL> (bulleted list) or <OL> (numbered list).","m":1},{"t":"The end tag </LI> is optional.","m":1}]},{"id":"cs-12-04-21","kind":"short","q":"What attributes can be used with <LI> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.21"],"model":[{"t":"TYPE: changes the bullet or number style of the item (disc, circle, square for UL; 1, A, a, I, i for OL).","m":1},{"t":"VALUE: sets the number of the item in an ordered list; the next items continue from it.","m":1},{"t":"Example: <LI TYPE=\"square\"> item </LI> and <LI VALUE=\"5\"> item </LI>.","m":1}]},{"id":"cs-12-04-22","kind":"short","q":"What are ordered lists ?","marks":3,"src":["Guide ch.4 HTML, Q.22"],"model":[{"t":"An ordered list is a list whose items are numbered or lettered in order. It is made with <OL> ... </OL>.","m":1},{"t":"Each item is written with <LI>. The TYPE attribute gives 1, A, a, I or i, and START gives the first number.","m":1},{"t":"Example: <OL TYPE=\"A\"> <LI> Hardware <LI> Software </OL>","m":1}]},{"id":"cs-12-04-23","kind":"short","q":"What are unordered lists ?","marks":3,"src":["Guide ch.4 HTML, Q.23"],"model":[{"t":"An unordered list shows its items with bullets, not numbers. It is made with <UL> ... </UL>.","m":1},{"t":"Each item is written with <LI>. TYPE gives the bullet: disc, circle or square.","m":1},{"t":"Example: <UL TYPE=\"circle\"> <LI> C++ <LI> HTML </UL>","m":1}]},{"id":"cs-12-04-24","kind":"short","q":"Explain how link is created in web page.","marks":4,"src":["Guide ch.4 HTML, Q.24"],"model":[{"t":"A link (hyperlink) is made with the anchor tag <A> ... </A> and its HREF attribute.","m":1},{"t":"HREF holds the address to go to: a file of the same site or a full URL.","m":1},{"t":"The text between the tags is the clickable part. Example: <A HREF=\"http://www.mit.org\">Website of MIT</A>","m":1},{"t":"For e-mail, HREF is \"mailto:name@site.com\". The NAME attribute makes a place inside a page to jump to.","m":1}]},{"id":"cs-12-04-25","kind":"short","q":"What is use of <SUB> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.25"],"model":[{"t":"The <SUB> tag shows the text as a subscript: smaller and a little below the line.","m":1},{"t":"Example: H<SUB>2</SUB>O is shown as H2O with a small lowered 2.","m":1},{"t":"It is used in chemical formulas and in mathematics. It needs the end tag </SUB>.","m":1}]},{"id":"cs-12-04-26","kind":"short","q":"What is use of <SUP> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.26"],"model":[{"t":"The <SUP> tag shows the text as a superscript: smaller and a little above the line.","m":1},{"t":"Example: X<SUP>2</SUP> is shown as X with a small raised 2.","m":1},{"t":"It is used for powers and for marks like 1st. It needs the end tag </SUP>.","m":1}]},{"id":"cs-12-04-27","kind":"short","q":"What is <FONT> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.27"],"model":[{"t":"The <FONT> tag changes the look of the text inside it.","m":1},{"t":"Attributes: SIZE (1 to 7), COLOR (a name or an RGB code) and FACE (the name of the font).","m":1},{"t":"Example: <FONT SIZE=\"5\" COLOR=\"red\" FACE=\"Arial\"> Hello </FONT>","m":1}]},{"id":"cs-12-04-28","kind":"short","q":"What is use of <BIG> and <SMALL> tags ?","marks":3,"src":["Guide ch.4 HTML, Q.28"],"model":[{"t":"<BIG> shows the text in a bigger size than the text around it.","m":1},{"t":"<SMALL> shows the text in a smaller size.","m":1},{"t":"Both need an end tag: <BIG> Big </BIG> <SMALL> small </SMALL>.","m":1}]},{"id":"cs-12-04-29","kind":"short","q":"What is RGB code ?","marks":3,"src":["Guide ch.4 HTML, Q.29"],"model":[{"t":"The RGB code is a way of giving a colour as a mix of Red, Green and Blue light.","m":1},{"t":"It is written as a hash and six hexadecimal digits: #RRGGBB, two digits for each colour (00 to FF).","m":1},{"t":"Examples: #FF0000 is red, #00FF00 is green, #0000FF is blue, #FFFF00 is yellow, #FFFFFF is white and #000000 is black.","m":1}]},{"id":"cs-12-04-30","kind":"short","q":"What is <IMG> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.30"],"model":[{"t":"The <IMG> tag puts a picture in the web page. It is an empty tag with no end tag.","m":1},{"t":"The SRC attribute gives the file name of the picture: <IMG SRC=\"photo.jpg\">.","m":1},{"t":"Other attributes are ALT, HEIGHT, WIDTH, BORDER and ALIGN.","m":1}]},{"id":"cs-12-04-31","kind":"short","q":"What is use of ALT attribute ? Why it is to be used ?","marks":3,"src":["Guide ch.4 HTML, Q.31"],"model":[{"t":"The ALT attribute gives alternate text for a picture: <IMG SRC=\"a.jpg\" ALT=\"My college\">.","m":1},{"t":"The text is shown if the picture cannot be loaded or if the browser does not show pictures.","m":1},{"t":"It is also read by screen readers for blind users, and it appears as a tip when the mouse is on the picture.","m":1}]},{"id":"cs-12-04-32","kind":"short","q":"Explain use of ALIGN attribute with <IMG> tag.","marks":3,"src":["Guide ch.4 HTML, Q.32"],"model":[{"t":"The ALIGN attribute decides where the picture is placed in relation to the text around it.","m":1},{"t":"Values: top, middle, bottom (the text goes along the picture), and left or right (the picture is at the side and the text flows around it).","m":1},{"t":"Example: <IMG SRC=\"a.jpg\" ALIGN=\"right\">","m":1}]},{"id":"cs-12-04-33","kind":"short","q":"What are Float and Inline images ?","marks":4,"src":["Guide ch.4 HTML, Q.33"],"model":[{"t":"An inline image is placed in the line of text, like a big letter. The text does not flow around it.","m":1},{"t":"A floating image is moved to the left or right margin with ALIGN=\"left\" or \"right\", and the text flows around it.","m":1},{"t":"An inline image is made with a simple <IMG SRC=\"a.jpg\">.","m":1},{"t":"A floating image is made with <IMG SRC=\"a.jpg\" ALIGN=\"left\">.","m":1}]},{"id":"cs-12-04-35","kind":"short","q":"What are different attributes of <TABLE > tag ?","marks":4,"src":["Guide ch.4 HTML, Q.35"],"model":[{"t":"BORDER: the thickness of the border lines. Without it the table has no lines.","m":1},{"t":"CELLPADDING: the space between the text and the cell border. CELLSPACING: the space between cells.","m":1},{"t":"WIDTH and HEIGHT: the size of the table in pixels or in per cent.","m":1},{"t":"ALIGN and BGCOLOR: the place of the table in the page and its background colour.","m":1}]},{"id":"cs-12-04-36","kind":"short","q":"What is <CAPTION> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.36"],"model":[{"t":"The <CAPTION> tag gives a title (heading) to a table.","m":1},{"t":"It is written just after the <TABLE> tag and ends with </CAPTION>.","m":1},{"t":"By default the caption is above the table; ALIGN=\"bottom\" puts it below.","m":1}]},{"id":"cs-12-04-37","kind":"short","q":"What is <TR> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.37"],"model":[{"t":"The <TR> tag (table row) starts one row of a table. It ends with </TR>.","m":1},{"t":"The cells of the row are written inside it with <TH> or <TD>.","m":1},{"t":"A table has as many <TR> parts as it has rows.","m":1}]},{"id":"cs-12-04-38","kind":"short","q":"What is <TH> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.38"],"model":[{"t":"The <TH> tag (table heading) makes a heading cell in a row.","m":1},{"t":"The text in it is shown in bold and in the centre by default.","m":1},{"t":"It ends with </TH> and is used for the first row or column of a table.","m":1}]},{"id":"cs-12-04-39","kind":"short","q":"What is <TD> tag ?","marks":3,"src":["Guide ch.4 HTML, Q.39"],"model":[{"t":"The <TD> tag (table data) makes an ordinary data cell in a row.","m":1},{"t":"The text in it is shown in normal type, to the left by default.","m":1},{"t":"It ends with </TD>. Its attributes include ALIGN, COLSPAN and ROWSPAN.","m":1}]},{"id":"cs-12-04-40","kind":"short","q":"What are COLSPAN and ROWSPAN attributes?","marks":4,"src":["Guide ch.4 HTML, Q.40"],"model":[{"t":"COLSPAN makes one cell go across several columns: <TH COLSPAN=\"3\"> Year </TH>.","m":1},{"t":"ROWSPAN makes one cell go down across several rows: <TD ROWSPAN=\"2\"> Sale </TD>.","m":1},{"t":"They are written inside <TH> or <TD>.","m":1},{"t":"The cells that are covered are left out of the code for the other rows or columns.","m":1}]},{"id":"cs-12-04-41","kind":"short","q":"What is script?","marks":3,"src":["Guide ch.4 HTML, Q.41"],"model":[{"t":"A script is a short program written inside a web page, which the browser runs.","m":1},{"t":"It is used to make the page respond: calculations, checking a form, messages and dates.","m":1},{"t":"It is written between <SCRIPT> and </SCRIPT> tags. Two languages are VBScript and JavaScript.","m":1}]},{"id":"cs-12-04-42","kind":"short","q":"What are advantages of using VBScript in HTML code ?","marks":4,"src":["Guide ch.4 HTML, Q.42"],"model":[{"t":"It makes a web page dynamic and interactive, because it can take decisions and do calculations.","m":1},{"t":"It is easy to learn, as it is like Visual Basic.","m":1},{"t":"It can check the data of a form on the user's computer, so the server is not troubled.","m":1},{"t":"It can use message boxes and input boxes, and it can change the page without loading it again.","m":1}]},{"id":"cs-12-04-43","kind":"prog","q":"Write HTML code for a web page for displaying information of company.","marks":5,"src":["Guide ch.4 HTML, Q.43"],"model":[{"t":"The page structure is correct: HTML, HEAD with TITLE, and BODY.","m":1},{"t":"A heading with the name of the company is written with a heading tag.","m":1},{"t":"Paragraphs give the details (address, work, contact) with formatting tags.","m":1},{"t":"A list or a table shows some facts (products or departments), and a link is given.","m":1},{"t":"All tags are closed in the right order.","m":1}],"code":"<HTML>\n<HEAD>\n<TITLE>Company information</TITLE>\n</HEAD>\n<BODY>\n<H1 ALIGN=\"center\">Sunrise Computers Pvt. Ltd.</H1>\n<HR>\n<P><B>About us:</B> We make and sell computers and give computer training.</P>\n<P><B>Address:</B><BR>\n12, Main Road,<BR>\nLatur - 413512</P>\n<H3>Our departments</H3>\n<UL TYPE=\"square\">\n<LI>Sales\n<LI>Service\n<LI>Training\n</UL>\n<P>Write to us: <A HREF=\"mailto:info@sunrise.com\">info@sunrise.com</A></P>\n</BODY>\n</HTML>"},{"id":"cs-12-04-44","kind":"prog","q":"Write HTML code for a web page displaying following :\nCollege Name : Modern College\nCourses | No. of Students\nB.A. | 200\nB.Com. | 100\nB.Sc. | 100","marks":4,"src":["Guide ch.4 HTML, Q.44"],"model":[{"t":"The page and the TABLE tag with a border are written correctly.","m":1},{"t":"The caption (or a heading cell with COLSPAN=\"2\") gives the college name.","m":1},{"t":"The heading row has the two headings, Courses and No. of Students.","m":1},{"t":"The three data rows are written with <TR> and <TD>, and all tags are closed.","m":1}],"code":"<HTML>\n<BODY>\n<TABLE BORDER=\"1\">\n<TR>\n<TH COLSPAN=\"2\">College Name : Modern College</TH>\n</TR>\n<TR>\n<TH>Courses</TH>\n<TH>No. of Students</TH>\n</TR>\n<TR>\n<TD>B.A.</TD>\n<TD>200</TD>\n</TR>\n<TR>\n<TD>B.Com.</TD>\n<TD>100</TD>\n</TR>\n<TR>\n<TD>B.Sc.</TD>\n<TD>100</TD>\n</TR>\n</TABLE>\n</BODY>\n</HTML>"},{"id":"cs-12-04-45","kind":"prog","q":"Write HTML code along with VBscript for a web page which displays a new digit number every time the page is visited.","marks":5,"src":["Guide ch.4 HTML, Q.45"],"model":[{"t":"The page structure is correct and the script is written between SCRIPT tags with the language VBScript.","m":1},{"t":"Randomize is used so that a different number comes each time the page opens.","m":1},{"t":"A random digit (0 to 9) is made with Rnd and Int, and kept in a variable.","m":1},{"t":"The digit is written in the page with document.write.","m":1},{"t":"The script and all tags are closed correctly.","m":1}],"code":"<HTML>\n<HEAD>\n<TITLE>Visit digit</TITLE>\n</HEAD>\n<BODY>\n<H3>Your digit for this visit is:</H3>\n<SCRIPT LANGUAGE=\"VBScript\">\n    Dim n\n    Randomize\n    n = Int(Rnd * 10)        ' a digit from 0 to 9\n    document.write(n)\n</SCRIPT>\n</BODY>\n</HTML>"},{"id":"cs-12-04-m46a","kind":"mcq","q":"HTML is ...................","marks":1,"src":["Guide ch.4 HTML, Q.46(a)"],"options":["Hyper Text Manipulation Language.","Hyper Text Mark up Language.","Hi Text Mark up Language.","None of these."],"ans":1,"why":"HTML stands for Hyper Text Markup Language."},{"id":"cs-12-04-m46b","kind":"mcq","q":"www is ...................","marks":1,"src":["Guide ch.4 HTML, Q.46(b)"],"options":["World wide web.","World wide wed.","Web wide world.","None of these."],"ans":0,"why":"WWW stands for World Wide Web."},{"id":"cs-12-04-m46c","kind":"mcq","q":"For yellow color, RGB code is ...................","marks":1,"src":["Guide ch.4 HTML, Q.46(c)"],"options":["# FF 00 FF.","# FF FF 00.","# 00 FFFF.","None of these."],"ans":1,"why":"Yellow is red plus green with no blue: #FF FF 00. #FF00FF is magenta and #00FFFF is cyan."},{"id":"cs-12-04-m46d","kind":"mcq","q":"................... tag is used to bold the text.","marks":1,"src":["Guide ch.4 HTML, Q.46(d)"],"options":["<BIG>","<B>","<U>","None of these"],"ans":1,"why":"<B> makes the text bold. <BIG> makes it bigger and <U> underlines it."},{"id":"cs-12-04-91","kind":"prog","q":"Write the exact output of the following HTML code with font specifications in brackets :\n<html>\n<body>\n<h1> LIST OF BOOKS </h1> <hr>\n<ul type = \"circle\">\n   <li> How to solve it By computer\n   <li> HTML in Easy Steps\n   <li> C++ Programming\n</ul>\n<ol type = \"A\">\n   <li> Microprocessor Programming\n   <li> Networking Essentials\n   <li> Microcontrollers\n</ol>\n<body>\n</html>","marks":4,"src":["Board paper March 2002 (printed in the guide, ch.4 p.173)"],"model":[{"t":"The heading LIST OF BOOKS is shown in the biggest heading style (h1, bold), with a horizontal line below it.","m":1},{"t":"The unordered list is shown with circle bullets: How to solve it By computer; HTML in Easy Steps; C++ Programming.","m":1},{"t":"The ordered list is shown with capital letters A, B, C as numbering.","m":1},{"t":"The three items of the ordered list are: Microprocessor Programming, Networking Essentials and Microcontrollers.","m":1}],"code":"LIST OF BOOKS            (h1, bold, large)\n---------------------------------\n o  How to solve it By computer\n o  HTML in Easy Steps\n o  C++ Programming\n A. Microprocessor Programming\n B. Networking Essentials\n C. Microcontrollers"},{"id":"cs-12-04-92","kind":"prog","q":"Write HTML code for the following table (March 2002):\nA table with a heading \"Year\" over the columns 1998, 1999 and 2000, and two rows, Units (500, 400, 1000) and Income (1000, 800, 2000), both under the label \"Sale\".","marks":5,"src":["Board paper March 2002 (printed in the guide, ch.4 p.173)"],"model":[{"t":"The table has a border and the page structure is correct.","m":1},{"t":"The empty top-left cell covers two rows and two columns (ROWSPAN and COLSPAN).","m":1},{"t":"The heading \"Year\" covers three columns with COLSPAN=\"3\", and the years 1998, 1999, 2000 come in the next row.","m":1},{"t":"\"Sale\" covers two rows with ROWSPAN=\"2\", and the rows Units and Income are written with their values.","m":1},{"t":"All tags are closed in the right order.","m":1}],"code":"<HTML>\n<BODY>\n<TABLE BORDER=\"1\">\n<TR>\n  <TH ROWSPAN=\"2\" COLSPAN=\"2\"></TH>\n  <TH COLSPAN=\"3\">Year</TH>\n</TR>\n<TR>\n  <TH>1998</TH><TH>1999</TH><TH>2000</TH>\n</TR>\n<TR>\n  <TH ROWSPAN=\"2\">Sale</TH>\n  <TH>Units</TH><TD>500</TD><TD>400</TD><TD>1000</TD>\n</TR>\n<TR>\n  <TH>Income</TH><TD>1000</TD><TD>800</TD><TD>2000</TD>\n</TR>\n</TABLE>\n</BODY>\n</HTML>"},{"id":"cs-12-04-93","kind":"prog","q":"Write HTML code for the following:\nA page titled SSC/HSC BOARD (heading size h1) with a table with the heading RESULT and the links SSC and HSC below it, then \"Contact me\" and \"Website of MIT\". Clicking SSC should open the page SSC.html, clicking HSC should open HSC.html, clicking \"Contact me\" should write an e-mail to result@hscboard.com, and clicking \"Website of MIT\" should open www.mit.org.","marks":5,"src":["Board paper, SSC/HSC result page (printed in the guide, ch.4 p.175)"],"model":[{"t":"The page, the title and the heading in h1 are written correctly.","m":1},{"t":"A table with a border has the heading RESULT across two columns (COLSPAN=\"2\").","m":1},{"t":"The next row has two cells with links to SSC.html and HSC.html.","m":1},{"t":"The e-mail link uses mailto: and the website link uses the full address http://www.mit.org/.","m":1},{"t":"All tags are closed in the right order.","m":1}],"code":"<HTML>\n<HEAD>\n<TITLE>SSC/HSC BOARD</TITLE>\n</HEAD>\n<BODY>\n<H1>SSC/HSC BOARD</H1>\n<TABLE BORDER=\"2\" CELLPADDING=\"5\" CELLSPACING=\"5\">\n<TR>\n  <TH COLSPAN=\"2\"><H2>RESULT</H2></TH>\n</TR>\n<TR>\n  <TH><H2><A HREF=\"SSC.html\">SSC</A></H2></TH>\n  <TH><H2><A HREF=\"HSC.html\">HSC</A></H2></TH>\n</TR>\n</TABLE>\n<H3><A HREF=\"mailto:result@hscboard.com\">Contact me</A></H3>\n<H3><A HREF=\"http://www.mit.org/\">Website of MIT</A></H3>\n</BODY>\n</HTML>"}];
